import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

// ═══════════════════════════════════════════════════════════════════════════════
// Types & constants — two-column layout: encoder left, decoder right.
// Canvas is intentionally narrow so fitToView keeps the diagram at ~1:1 scale.
// ═══════════════════════════════════════════════════════════════════════════════

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;
const LEFT_CX = 240;
const RIGHT_CX = 720;

const COLORS = {
  input: { fill: '#e8f5e9', stroke: '#4caf50' },
  norm: { fill: '#fff8e1', stroke: '#f9a825' },
  attn: { fill: '#e3f2fd', stroke: '#1976d2' },
  cross: { fill: '#ede7f6', stroke: '#5e35b1' },
  mlp: { fill: '#fff3e0', stroke: '#f57c00' },
  weight: { fill: '#f1f5f9', stroke: '#64748b' },
  score: { fill: '#fce4ec', stroke: '#c2185b' },
  softmax: { fill: '#fff8e1', stroke: '#f9a825' },
  output: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  residual: { fill: '#e8f5e9', stroke: '#4caf50' },
  mask: { fill: '#eceff1', stroke: '#546e7a' },
  text: 'var(--text)',
  muted: 'var(--text-muted)',
};

const STEP_GROUPS = {
  encInput: 'step-ed-enc-input',
  encNorm1: 'step-ed-enc-norm1',
  encAttn: 'step-ed-enc-attn',
  encRes1: 'step-ed-enc-res1',
  encNorm2: 'step-ed-enc-norm2',
  encMlp: 'step-ed-enc-mlp',
  encRes2: 'step-ed-enc-res2',
  encOutput: 'step-ed-enc-output',
  decInput: 'step-ed-dec-input',
  decNorm1: 'step-ed-dec-norm1',
  decAttn: 'step-ed-dec-attn',
  decRes1: 'step-ed-dec-res1',
  crossNorm: 'step-ed-cross-norm',
  crossAttn: 'step-ed-cross-attn',
  decRes2: 'step-ed-dec-res2',
  decNorm3: 'step-ed-dec-norm3',
  decMlp: 'step-ed-dec-mlp',
  decRes3: 'step-ed-dec-res3',
  decOutput: 'step-ed-dec-output',
};

const BOX_H = 76;
const BOX_W = 460;
const MAT_H = 72;
const VEC_H = 36;
const VEC_W = 130;
const WEIGHT_W = 108;
const WEIGHT_H = 82;
const SEQ_W = 160;
const GROUP_GAP = 130;
const BOX_TO_ROW_GAP = 72;
const VERTICAL_ARROW_LEN = 68;
const ROW_EQ_GAP = 66;
const RESIDUAL_OFFSET = 210;

interface BlockStep extends StepInfo {}

interface BlockParams {
  dModel: number;
  nHeads: number;
  encLen: number;
  decLen: number;
  dFf: number;
  normType: string;
  dHead: number;
}

interface SubLayerResult {
  bottom: number;
  outputCy: number;
  startY: number;
  kvInputCy?: number;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel, x1: number, x2: number, y: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function startGroup(g: Gsel, className: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel,
  cx: number,
  y: number,
  stepNum: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string,
  width = BOX_W
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - width / 2)
    .attr('y', y)
    .attr('width', width)
    .attr('height', BOX_H)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  grp.append('circle')
    .attr('cx', cx - width / 2 + 22)
    .attr('cy', y + BOX_H / 2)
    .attr('r', 15)
    .attr('fill', stroke);
  lbl(grp, cx - width / 2 + 22, y + BOX_H / 2 + 1, String(stepNum), { size: 14, weight: '700', color: '#fff' });

  lbl(grp, cx - width / 2 + 44, y + 26, title, {
    size: 15,
    weight: '600',
    color: 'var(--text)',
    anchor: 'start',
  });
  lbl(grp, cx - width / 2 + 44, y + 52, formula, {
    size: 11,
    color: 'var(--text-muted)',
    font: 'monospace',
    anchor: 'start',
  });
  return y + BOX_H;
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle')
    .attr('cx', cx)
    .attr('cy', cy)
    .attr('r', 16)
    .attr('fill', '#fff')
    .attr('stroke', color)
    .attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function drawSeqMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.input.fill,
  stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x - SEQ_W / 2, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 5,
    dimTop: 'S',
    dimRight: 'D',
  });
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke,
  width = WEIGHT_W,
  height = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - height / 2, {
    width,
    height,
    label,
    sublabel,
    fill,
    stroke,
    cols: 5,
    rows: 5,
  });
}

function drawSmallVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  width = VEC_W
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - VEC_H / 2, {
    width,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 1,
  });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const badgeW = Math.max(86, text.length * 7.5 + 18);
  const badgeH = VEC_H;
  g.append('rect')
    .attr('x', cx - badgeW / 2)
    .attr('y', cy - badgeH / 2)
    .attr('width', badgeW)
    .attr('height', badgeH)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  lbl(g, cx, cy, text, { size: 11, weight: '600', color: stroke });
}

function drawResidualPath(
  g: Gsel,
  cx: number,
  startX: number,
  startY: number,
  endX: number,
  endY: number,
  options: { color?: string; label?: string } = {}
): void {
  const { color = COLORS.residual.stroke, label = 'residual' } = options;
  const side = cx >= CX ? 'right' : 'left';
  const farX = side === 'right' ? cx + RESIDUAL_OFFSET : cx - RESIDUAL_OFFSET;
  const path = `M ${startX},${startY} L ${farX},${startY} L ${farX},${endY} L ${endX},${endY}`;
  g.append('path')
    .attr('d', path)
    .attr('fill', 'none')
    .attr('stroke', color)
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '5,3')
    .attr('opacity', 0.75);
  const labelAnchor = side === 'right' ? 'start' : 'end';
  const labelX = side === 'right' ? farX + 8 : farX - 8;
  lbl(g, labelX, (startY + endY) / 2, label, { size: 10, color, anchor: labelAnchor });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Parameter summary
// ═══════════════════════════════════════════════════════════════════════════════

function drawParamSummary(g: Gsel, y: number, p: BlockParams): number {
  const SUM_W = 720;
  const SUM_H = 74;
  const grp = g.append('g').attr('transform', `translate(${CX - SUM_W / 2}, ${y})`);
  grp.append('rect')
    .attr('width', SUM_W)
    .attr('height', SUM_H)
    .attr('rx', 8)
    .attr('fill', 'var(--surface)')
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 1);
  lbl(grp, 14, 16, 'Parameters →', { size: 10, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model=${p.dModel}`, meta: 'hidden', color: '#4caf50' },
    { label: `n_heads=${p.nHeads}`, meta: 'heads', color: '#1976d2' },
    { label: `enc_len=${p.encLen}`, meta: 'encoder tokens', color: '#7b1fa2' },
    { label: `dec_len=${p.decLen}`, meta: 'decoder tokens', color: '#5e35b1' },
    { label: `d_ff=${p.dFf}`, meta: 'FFN', color: '#f57c00' },
    { label: `d_head=${p.dHead}`, meta: 'per head', color: '#009688' },
    { label: `norm=${p.normType}`, meta: 'norm', color: '#f9a825' },
    { label: `arch=pre-norm`, meta: 'style', color: '#1565c0' },
  ];
  const cols = 4;
  const itemW = 178;
  const itemH = 30;
  const startX = 8;
  const startY = 24;
  items.forEach((item, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const px = startX + col * itemW;
    const py = startY + row * itemH;
    grp.append('rect')
      .attr('x', px)
      .attr('y', py)
      .attr('width', itemW - 8)
      .attr('height', itemH - 4)
      .attr('rx', 6)
      .attr('fill', hexWithAlpha(item.color, 0.08))
      .attr('stroke', item.color)
      .attr('stroke-width', 1);
    lbl(grp, px + 8, py + 12, item.label, {
      size: 10,
      weight: '600',
      color: item.color,
      font: 'monospace',
      anchor: 'start',
    });
    lbl(grp, px + 8, py + 22, `→ ${item.meta}`, { size: 8, color: item.color, anchor: 'start' });
  });
  return y + SUM_H + 14;
}

function hexWithAlpha(hex: string, alpha: number): string {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Attention sub-layer — explicit vertical pipeline
// ═══════════════════════════════════════════════════════════════════════════════

interface AttnOptions {
  kind: 'encoder-self' | 'decoder-causal' | 'cross';
  withNorm: boolean;
  residualStartY: number;
  sourceLen?: number;
  targetLen?: number;
}

function drawAttentionSubLayer(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  p: BlockParams,
  opts: AttnOptions
): SubLayerResult {
  const { kind, withNorm, residualStartY, sourceLen = p.encLen, targetLen = p.decLen } = opts;
  const isCross = kind === 'cross';
  const isCausal = kind === 'decoder-causal';
  const titlePrefix = isCross ? 'Cross-Attention' : isCausal ? 'Causal Self-Attention' : 'Bidirectional Self-Attention';
  const formula = withNorm ? `${p.normType} + MHA` : 'MHA';
  const stroke = isCross ? COLORS.cross.stroke : COLORS.attn.stroke;
  const fill = isCross ? COLORS.cross.fill : COLORS.attn.fill;
  const sLabel = isCross ? 'S_enc' : 'S';
  const tLabel = isCross ? 'S_dec' : 'S';
  const seqLen = isCross ? targetLen : sourceLen;
  const kvLen = isCross ? sourceLen : seqLen;

  const grp = startGroup(g, isCross ? STEP_GROUPS.crossAttn : kind === 'decoder-causal' ? STEP_GROUPS.decAttn : STEP_GROUPS.encAttn, stepId);
  const headerBottom = stepHeader(grp, cx, y, stepId, titlePrefix, formula, fill, stroke, BOX_W);

  let cy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  let xNormBottom = cy;

  // 1. Input norm + x_norm
  if (withNorm) {
    if (isCross) {
      // Cross-attention: x_norm feeds only Q; K/V come from encoder output later.
      const normBadgeX = cx - 260;
      drawBadge(grp, normBadgeX, cy, p.normType, COLORS.norm.fill, COLORS.norm.stroke);
      drawSmallVector(grp, cx - 120, cy, 'x_norm', `[B, ${seqLen}, ${p.dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 130);
      arrowH(grp, normBadgeX + 43, cx - 120 - 65, cy, COLORS.norm.stroke);
    } else {
      const normBadgeX = cx - 150;
      drawBadge(grp, normBadgeX, cy, p.normType, COLORS.norm.fill, COLORS.norm.stroke);
      drawSmallVector(grp, cx, cy, 'x_norm', `[B, ${seqLen}, ${p.dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 130);
      arrowH(grp, normBadgeX + 43, cx - 65, cy, COLORS.norm.stroke);
    }
    xNormBottom = cy + VEC_H / 2;
    cy += VEC_H / 2 + VERTICAL_ARROW_LEN;
  } else {
    drawSmallVector(grp, cx, cy, 'x', `[B, ${seqLen}, ${p.dModel}]`, fill, stroke, 130);
    xNormBottom = cy + VEC_H / 2;
    cy += VEC_H / 2 + VERTICAL_ARROW_LEN;
  }

  // Remember weight-row center for the cross-attn K/V arrow.
  const kvInputCy = cy;

  // 2. Q / K / V projections
  const qx = cx - 120;
  const kx = cx;
  const vx = cx + 120;
  drawWeightMatrix(grp, qx, cy, 'W_q', `[D, D]`, COLORS.weight.fill, COLORS.weight.stroke);
  drawWeightMatrix(grp, kx, cy, 'W_k', `[D, D]`, COLORS.weight.fill, COLORS.weight.stroke);
  drawWeightMatrix(grp, vx, cy, 'W_v', `[D, D]`, COLORS.weight.fill, COLORS.weight.stroke);
  arrowDown(grp, qx, xNormBottom, cy - WEIGHT_H / 2, stroke);
  if (!isCross) {
    arrowDown(grp, kx, xNormBottom, cy - WEIGHT_H / 2, stroke);
    arrowDown(grp, vx, xNormBottom, cy - WEIGHT_H / 2, stroke);
  }

  const qkvOutY = cy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, qx, qkvOutY, 'Q', `[B, ${seqLen}, D]`, fill, stroke, 100);
  drawSmallVector(grp, kx, qkvOutY, 'K', `[B, ${kvLen}, D]`, fill, stroke, 100);
  drawSmallVector(grp, vx, qkvOutY, 'V', `[B, ${kvLen}, D]`, fill, stroke, 100);
  arrowDown(grp, qx, cy + WEIGHT_H / 2, qkvOutY - VEC_H / 2, COLORS.weight.stroke);
  arrowDown(grp, kx, cy + WEIGHT_H / 2, qkvOutY - VEC_H / 2, COLORS.weight.stroke);
  arrowDown(grp, vx, cy + WEIGHT_H / 2, qkvOutY - VEC_H / 2, COLORS.weight.stroke);

  // 3. Head split note
  cy = qkvOutY + VEC_H / 2 + 42;
  lbl(grp, cx, cy, `reshape into ${p.nHeads} heads · d_head=${p.dHead}`, { size: 11, color: COLORS.muted, font: 'monospace' });
  cy += 42;

  // 4. Q @ K^T / √d_h  →  scores
  drawSmallVector(grp, cx - 130, cy, 'Q', `[B, n_h, ${tLabel}, d_h]`, fill, stroke, 90);
  drawSmallVector(grp, cx + 130, cy, 'K', `[B, n_h, ${sLabel}, d_h]`, fill, stroke, 90);
  drawBadge(grp, cx, cy, 'Q @ K^T / √d_h', COLORS.score.fill, COLORS.score.stroke);
  arrowH(grp, cx - 130 + 45, cx - 66, cy, COLORS.score.stroke);
  arrowH(grp, cx + 66, cx + 130 - 45, cy, COLORS.score.stroke);
  const scoresY = cy + VEC_H / 2 + VERTICAL_ARROW_LEN;
  drawSmallVector(grp, cx, scoresY, 'scores', `[B, n_h, ${tLabel}, ${sLabel}]`, COLORS.score.fill, COLORS.score.stroke, 120);
  arrowDown(grp, cx, cy + VEC_H / 2, scoresY - VEC_H / 2, COLORS.score.stroke);
  cy = scoresY + VEC_H / 2 + ROW_EQ_GAP;

  // 5. Optional causal mask
  if (isCausal) {
    drawBadge(grp, cx, cy, 'causal mask', COLORS.mask.fill, COLORS.mask.stroke);
    arrowDown(grp, cx, scoresY + VEC_H / 2, cy - VEC_H / 2, COLORS.mask.stroke);
    const maskedY = cy + VEC_H / 2 + VERTICAL_ARROW_LEN;
    drawSmallVector(grp, cx, maskedY, 'masked', `[B, n_h, ${tLabel}, ${sLabel}]`, COLORS.mask.fill, COLORS.mask.stroke, 120);
    arrowDown(grp, cx, cy + VEC_H / 2, maskedY - VEC_H / 2, COLORS.mask.stroke);
    cy = maskedY + VEC_H / 2 + ROW_EQ_GAP;
  }

  // 6. Softmax  →  attention weights A
  drawBadge(grp, cx, cy, 'softmax', COLORS.softmax.fill, COLORS.softmax.stroke);
  const prevY = isCausal ? cy - VEC_H / 2 - VERTICAL_ARROW_LEN : scoresY;
  arrowDown(grp, cx, prevY + VEC_H / 2, cy - VEC_H / 2, COLORS.softmax.stroke);
  const aY = cy + VEC_H / 2 + VERTICAL_ARROW_LEN;
  drawSmallVector(grp, cx, aY, 'A', `[B, n_h, ${tLabel}, ${sLabel}]`, COLORS.softmax.fill, COLORS.softmax.stroke, 120);
  arrowDown(grp, cx, cy + VEC_H / 2, aY - VEC_H / 2, COLORS.softmax.stroke);
  cy = aY + VEC_H / 2 + ROW_EQ_GAP;

  // 7. A @ V  →  context
  drawSmallVector(grp, cx - 110, cy, 'A', `[B, n_h, ${tLabel}, ${sLabel}]`, COLORS.softmax.fill, COLORS.softmax.stroke, 90);
  drawSmallVector(grp, cx + 110, cy, 'V', `[B, n_h, ${sLabel}, d_h]`, fill, stroke, 90);
  drawBadge(grp, cx, cy, 'A @ V', fill, stroke);
  arrowH(grp, cx - 110 + 45, cx - 48, cy, COLORS.softmax.stroke);
  arrowH(grp, cx + 48, cx + 110 - 45, cy, fill);
  const contextY = cy + VEC_H / 2 + VERTICAL_ARROW_LEN;
  drawSmallVector(grp, cx, contextY, 'context', `[B, n_h, ${tLabel}, d_h]`, fill, stroke, 120);
  arrowDown(grp, cx, cy + VEC_H / 2, contextY - VEC_H / 2, fill);
  cy = contextY + VEC_H / 2 + ROW_EQ_GAP;

  // 8. Output projection W_o  →  attn_out / cross_out
  drawWeightMatrix(grp, cx, cy, 'W_o', `[D, D]`, COLORS.weight.fill, COLORS.weight.stroke);
  arrowDown(grp, cx, contextY + VEC_H / 2, cy - WEIGHT_H / 2, COLORS.weight.stroke);
  const outY = cy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN;
  drawSmallVector(grp, cx, outY, isCross ? 'cross_out' : 'attn_out', `[B, ${seqLen}, D]`, fill, stroke, 130);
  arrowDown(grp, cx, cy + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);

  return { bottom: outY + VEC_H / 2 + 28, outputCy: outY, startY: residualStartY, kvInputCy };
}

// ═══════════════════════════════════════════════════════════════════════════════
// FFN sub-layer — explicit vertical pipeline
// ═══════════════════════════════════════════════════════════════════════════════

function drawFfnSubLayer(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  p: BlockParams,
  withNorm: boolean,
  residualStartY: number,
  seqLen: number,
  groupName: string,
  stroke: string,
  fill: string
): SubLayerResult {
  const grp = startGroup(g, groupName, stepId);
  const title = 'FFN';
  const formula = withNorm ? `${p.normType} + FFN` : 'FFN';
  const headerBottom = stepHeader(grp, cx, y, stepId, title, formula, fill, stroke, BOX_W);

  let cy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;

  // 1. Input norm + x_norm
  if (withNorm) {
    drawBadge(grp, cx - 80, cy, p.normType, COLORS.norm.fill, COLORS.norm.stroke);
    drawSmallVector(grp, cx + 70, cy, 'x_norm', `[B, ${seqLen}, ${p.dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 130);
    arrowH(grp, cx - 80 + 43, cx + 70 - 55, cy, COLORS.norm.stroke);
    cy += VEC_H / 2 + VERTICAL_ARROW_LEN;
  } else {
    drawSmallVector(grp, cx, cy, 'x', `[B, ${seqLen}, ${p.dModel}]`, fill, stroke, 130);
    cy += VEC_H / 2 + VERTICAL_ARROW_LEN;
  }

  // 2. W_up  →  up
  drawWeightMatrix(grp, cx, cy, 'W_up', `[${p.dModel}, ${p.dFf}]`, COLORS.weight.fill, COLORS.weight.stroke);
  const upY = cy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, upY, 'up', `[B, ${seqLen}, ${p.dFf}]`, fill, stroke, 130);
  arrowDown(grp, cx, cy + WEIGHT_H / 2, upY - VEC_H / 2, COLORS.weight.stroke);
  lbl(grp, cx + 66, cy + WEIGHT_H / 2 + 10, 'x @ W_up', { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  // 3. GELU activation
  const actY = upY + VEC_H / 2 + ROW_EQ_GAP;
  drawBadge(grp, cx, actY, 'GELU', fill, stroke);
  arrowDown(grp, cx, upY + VEC_H / 2, actY - VEC_H / 2, COLORS.weight.stroke);
  const actOutY = actY + VEC_H / 2 + VERTICAL_ARROW_LEN;
  drawSmallVector(grp, cx, actOutY, 'activated', `[B, ${seqLen}, ${p.dFf}]`, fill, stroke, 130);
  arrowDown(grp, cx, actY + VEC_H / 2, actOutY - VEC_H / 2, stroke);

  // 4. W_down  →  ffn_out
  const downY = actOutY + VEC_H / 2 + ROW_EQ_GAP;
  drawWeightMatrix(grp, cx, downY, 'W_down', `[${p.dFf}, ${p.dModel}]`, COLORS.weight.fill, COLORS.weight.stroke);
  arrowDown(grp, cx, actOutY + VEC_H / 2, downY - WEIGHT_H / 2, COLORS.weight.stroke);
  const outY = downY + WEIGHT_H / 2 + VERTICAL_ARROW_LEN;
  drawSmallVector(grp, cx, outY, 'ffn_out', `[B, ${seqLen}, ${p.dModel}]`, fill, stroke, 130);
  arrowDown(grp, cx, downY + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);
  lbl(grp, cx + 66, downY + WEIGHT_H / 2 + 10, 'up @ W_down', { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  return { bottom: outY + VEC_H / 2 + 26, outputCy: outY, startY: residualStartY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Residual add
// ═══════════════════════════════════════════════════════════════════════════════

function drawResidualAdd(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  groupName: string,
  formula: string,
  label: string,
  subLayer: SubLayerResult,
  dModel: number,
  seqLen: number,
  outputLabel = 'residual_out'
): number {
  const grp = startGroup(g, groupName, stepId);
  const headerBottom = stepHeader(grp, cx, y, stepId, label, formula, COLORS.residual.fill, COLORS.residual.stroke, BOX_W);

  const cy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  opCircle(grp, cx, cy, '⊕', COLORS.residual.stroke);
  drawSmallVector(grp, cx - 90, cy, 'sub_out', `[B, ${seqLen}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 110);
  arrowDown(grp, cx, cy - 46, cy - 19, COLORS.attn.stroke);

  const startX = cx + SEQ_W / 2 + 4;
  const endX = cx + 18;
  drawResidualPath(grp, cx, startX, subLayer.startY, endX, cy, { color: COLORS.residual.stroke });

  const outCy = cy + VEC_H / 2 + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, outCy, outputLabel, `[B, ${seqLen}, ${dModel}]`, COLORS.residual.fill, COLORS.residual.stroke, 130);
  arrowDown(grp, cx, cy + 18, outCy - VEC_H / 2, COLORS.residual.stroke);

  return outCy + VEC_H / 2 + 14;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Input / Output steps
// ═══════════════════════════════════════════════════════════════════════════════

function drawInputStep(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  p: BlockParams,
  kind: 'encoder' | 'decoder'
): number {
  const isEnc = kind === 'encoder';
  const grp = startGroup(g, isEnc ? STEP_GROUPS.encInput : STEP_GROUPS.decInput, stepId);
  const seqLen = isEnc ? p.encLen : p.decLen;
  const name = isEnc ? 'Encoder input' : 'Decoder input';
  const varName = isEnc ? 'enc_in' : 'dec_in';
  const headerBottom = stepHeader(grp, cx, y, stepId, name, `${varName} ∈ ℝ^(B×${seqLen}×${p.dModel})`, COLORS.input.fill, COLORS.input.stroke, BOX_W);

  const cy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, cy, varName, `[B, ${seqLen}, ${p.dModel}]`, COLORS.input.fill, COLORS.input.stroke);
  const note = isEnc
    ? 'source token hidden states (bidirectional context)'
    : 'target token hidden states (causal, left-to-right)';
  lbl(grp, cx, cy + MAT_H / 2 + 18, note, { size: 11, color: COLORS.muted });
  return cy + MAT_H / 2 + 30;
}

function drawOutputStep(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  p: BlockParams,
  kind: 'encoder' | 'decoder'
): number {
  const isEnc = kind === 'encoder';
  const grp = startGroup(g, isEnc ? STEP_GROUPS.encOutput : STEP_GROUPS.decOutput, stepId);
  const seqLen = isEnc ? p.encLen : p.decLen;
  const name = isEnc ? 'Encoder output' : 'Decoder output';
  const varName = isEnc ? 'enc_out' : 'dec_out';
  const headerBottom = stepHeader(grp, cx, y, stepId, name, `${varName} ∈ ℝ^(B×${seqLen}×${p.dModel})`, COLORS.output.fill, COLORS.output.stroke, BOX_W);

  const cy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, cy, varName, `[B, ${seqLen}, ${p.dModel}]`, COLORS.output.fill, COLORS.output.stroke);
  const note = isEnc
    ? 'context vectors fed to decoder cross-attention K/V'
    : 'final decoder hidden states for the next block / LM head';
  lbl(grp, cx, cy + MAT_H / 2 + 18, note, { size: 11, color: COLORS.muted });
  return cy + MAT_H / 2 + 30;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main diagram
// ═══════════════════════════════════════════════════════════════════════════════

export function renderEncoderDecoderBlockDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const p: BlockParams = {
    dModel: Number(params.d_model) || 512,
    nHeads: Number(params.n_heads) || 8,
    encLen: Number(params.enc_len) || 128,
    decLen: Number(params.dec_len) || 64,
    dFf: Number(params.d_ff) || 2048,
    normType: String(params.norm_type || 'LayerNorm'),
    dHead: 0,
  };
  p.dHead = Math.floor(p.dModel / p.nHeads);

  const root = g as unknown as Gsel;
  let y = 26;

  // Title
  lbl(root, CX, y, 'Encoder-Decoder Block', { size: 18, weight: '700', color: COLORS.text });
  y += 20;
  lbl(
    root,
    CX,
    y,
    `pre-norm · ${p.normType} · d_model=${p.dModel} · n_heads=${p.nHeads} · d_head=${p.dHead} · enc_len=${p.encLen} · dec_len=${p.decLen} · d_ff=${p.dFf}`,
    { size: 11, color: COLORS.muted }
  );
  y += 26;

  y = drawParamSummary(root, y, p);

  // Column labels
  lbl(root, LEFT_CX, y, 'Encoder stack', { size: 14, weight: '700', color: COLORS.attn.stroke });
  lbl(root, RIGHT_CX, y, 'Decoder stack', { size: 14, weight: '700', color: COLORS.cross.stroke });
  y += 26;

  const steps: BlockStep[] = [];

  // ── Inputs ──
  const encInputBottom = drawInputStep(root, LEFT_CX, y, 1, p, 'encoder');
  const decInputBottom = drawInputStep(root, RIGHT_CX, y, 2, p, 'decoder');
  steps.push(makeInputStep(1, p, 'encoder'));
  steps.push(makeInputStep(2, p, 'decoder'));
  y = Math.max(encInputBottom, decInputBottom) + GROUP_GAP;

  // ── Encoder self-attention ──
  const encAttnStartY = encInputBottom - 28;
  const encAttnResult = drawAttentionSubLayer(root, LEFT_CX, y, 3, p, {
    kind: 'encoder-self',
    withNorm: true,
    residualStartY: encAttnStartY,
    sourceLen: p.encLen,
    targetLen: p.encLen,
  });
  steps.push(makeNormStep(3, `${p.normType} (pre-enc-attn)`, 'encAttn', p));
  steps.push(makeAttnStep(4, 'Bidirectional Self-Attention', 'encAttn', p, p.encLen));
  y = encAttnResult.bottom + GROUP_GAP;

  // ── Encoder residual 1 ──
  const encRes1Bottom = drawResidualAdd(root, LEFT_CX, y, 5, STEP_GROUPS.encRes1, 'enc_add1 = enc_in + attn_out', 'Encoder Residual Add 1', encAttnResult, p.dModel, p.encLen, 'enc_add1');
  steps.push(makeResStep(5, 1, 'Encoder', 'enc_add1 = enc_in + attn_out', 'encRes1'));
  y = encRes1Bottom + GROUP_GAP;

  // ── Encoder FFN ──
  const encFfnStartY = encRes1Bottom - 22;
  const encFfnResult = drawFfnSubLayer(root, LEFT_CX, y, 6, p, true, encFfnStartY, p.encLen, STEP_GROUPS.encMlp, COLORS.mlp.stroke, COLORS.mlp.fill);
  steps.push(makeNormStep(6, `${p.normType} (pre-enc-FFN)`, 'encMlp', p));
  steps.push(makeFfnStep(7, 'Encoder FFN', 'encMlp', p, p.encLen));
  y = encFfnResult.bottom + GROUP_GAP;

  // ── Encoder residual 2 + output ──
  const encRes2Bottom = drawResidualAdd(root, LEFT_CX, y, 8, STEP_GROUPS.encRes2, 'enc_out = enc_add1 + ffn_out', 'Encoder Residual Add 2', encFfnResult, p.dModel, p.encLen, 'enc_out');
  steps.push(makeResStep(8, 2, 'Encoder', 'enc_out = enc_add1 + ffn_out', 'encRes2'));
  y = encRes2Bottom + GROUP_GAP;

  const encOutputBottom = drawOutputStep(root, LEFT_CX, y, 9, p, 'encoder');
  steps.push(makeOutputStep(9, p, 'encoder'));

  // ── Decoder stack ──
  let decY = Math.max(encInputBottom, decInputBottom) + GROUP_GAP;

  // Decoder self-attention
  const decAttnStartY = decInputBottom - 28;
  const decAttnResult = drawAttentionSubLayer(root, RIGHT_CX, decY, 10, p, {
    kind: 'decoder-causal',
    withNorm: true,
    residualStartY: decAttnStartY,
    sourceLen: p.decLen,
    targetLen: p.decLen,
  });
  steps.push(makeNormStep(10, `${p.normType} (pre-dec-attn)`, 'decAttn', p));
  steps.push(makeAttnStep(11, 'Causal Self-Attention', 'decAttn', p, p.decLen));
  decY = decAttnResult.bottom + GROUP_GAP;

  // Decoder residual 1
  const decRes1Bottom = drawResidualAdd(root, RIGHT_CX, decY, 12, STEP_GROUPS.decRes1, 'dec_add1 = dec_in + attn_out', 'Decoder Residual Add 1', decAttnResult, p.dModel, p.decLen, 'dec_add1');
  steps.push(makeResStep(12, 1, 'Decoder', 'dec_add1 = dec_in + attn_out', 'decRes1'));
  decY = decRes1Bottom + GROUP_GAP;

  // Cross-attention: Q from decoder, K/V from encoder output
  const crossStartY = decRes1Bottom - 22;
  const crossResult = drawAttentionSubLayer(root, RIGHT_CX, decY, 13, p, {
    kind: 'cross',
    withNorm: true,
    residualStartY: crossStartY,
    sourceLen: p.encLen,
    targetLen: p.decLen,
  });
  steps.push(makeNormStep(13, `${p.normType} (pre-cross-attn)`, 'crossAttn', p));
  steps.push(makeAttnStep(14, 'Cross-Attention', 'crossAttn', p, p.decLen));

  // Encoder output → cross K/V arrow (route around the right side, above x_norm, into K and V)
  const encOutY = encOutputBottom - MAT_H / 2 - 10;
  const crossKvY = crossResult.kvInputCy ?? crossResult.outputCy;
  const crossTopY = crossKvY - WEIGHT_H / 2 - VERTICAL_ARROW_LEN - VEC_H + 16;
  const farX = RIGHT_CX + RESIDUAL_OFFSET + 80;
  const wkX = RIGHT_CX;
  const wvX = RIGHT_CX + 120;

  const crossGrp = root.append('g');
  const path = `M ${LEFT_CX + SEQ_W / 2 + 4},${encOutY} L ${farX},${encOutY} L ${farX},${crossTopY} L ${wvX},${crossTopY}`;
  crossGrp.append('path')
    .attr('d', path)
    .attr('fill', 'none')
    .attr('stroke', COLORS.output.stroke)
    .attr('stroke-width', 2)
    .attr('opacity', 0.85);
  // Branch to V
  drawArrow(crossGrp as unknown as Sel, wvX, crossTopY, wvX, crossKvY - WEIGHT_H / 2, { color: COLORS.output.stroke });
  // Branch to K
  crossGrp.append('line')
    .attr('x1', wvX)
    .attr('y1', crossTopY)
    .attr('x2', wkX)
    .attr('y2', crossTopY)
    .attr('stroke', COLORS.output.stroke)
    .attr('stroke-width', 2)
    .attr('opacity', 0.85);
  drawArrow(crossGrp as unknown as Sel, wkX, crossTopY, wkX, crossKvY - WEIGHT_H / 2, { color: COLORS.output.stroke });
  lbl(crossGrp, RIGHT_CX + 80, crossTopY - 12, 'enc_out → K,V for cross-attention', {
    size: 11,
    color: COLORS.output.stroke,
    font: 'monospace',
  });

  decY = crossResult.bottom + GROUP_GAP;

  // Decoder residual 2
  const decRes2Bottom = drawResidualAdd(root, RIGHT_CX, decY, 15, STEP_GROUPS.decRes2, 'dec_add2 = dec_add1 + cross_out', 'Decoder Residual Add 2', crossResult, p.dModel, p.decLen, 'dec_add2');
  steps.push(makeResStep(15, 2, 'Decoder', 'dec_add2 = dec_add1 + cross_out', 'decRes2'));
  decY = decRes2Bottom + GROUP_GAP;

  // Decoder FFN
  const decFfnStartY = decRes2Bottom - 22;
  const decFfnResult = drawFfnSubLayer(root, RIGHT_CX, decY, 16, p, true, decFfnStartY, p.decLen, STEP_GROUPS.decMlp, COLORS.mlp.stroke, COLORS.mlp.fill);
  steps.push(makeNormStep(16, `${p.normType} (pre-dec-FFN)`, 'decMlp', p));
  steps.push(makeFfnStep(17, 'Decoder FFN', 'decMlp', p, p.decLen));
  decY = decFfnResult.bottom + GROUP_GAP;

  // Decoder residual 3 + output
  const decRes3Bottom = drawResidualAdd(root, RIGHT_CX, decY, 18, STEP_GROUPS.decRes3, 'dec_out = dec_add2 + ffn_out', 'Decoder Residual Add 3', decFfnResult, p.dModel, p.decLen, 'dec_out');
  steps.push(makeResStep(18, 3, 'Decoder', 'dec_out = dec_add2 + ffn_out', 'decRes3'));
  decY = decRes3Bottom + GROUP_GAP;

  const decOutputBottom = drawOutputStep(root, RIGHT_CX, decY, 19, p, 'decoder');
  steps.push(makeOutputStep(19, p, 'decoder'));

  let footerY = Math.max(encOutputBottom, decOutputBottom) + 36;

  // Parameter / FLOP summary
  const metrics = computeMetrics(p);
  lbl(
    root,
    CX,
    footerY + 14,
    `Params: ${fmtNum(metrics.totalParams)} (attn ${fmtNum(metrics.attnParams)} + FFN ${fmtNum(metrics.ffnParams)} + norm ${fmtNum(metrics.normParams)}) · ~${fmtNum(metrics.flopsPerBlock)} FLOPs/block`,
    { size: 11, color: COLORS.muted, font: 'monospace' }
  );
  footerY += 38;

  // Explanations
  footerY = drawExplanation(g, 80, footerY, W - 160, insightText(p), 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText(p, metrics), 'perf');
  footerY += 12;

  // Cross-links
  drawComponentLink(g, CX - 190, footerY, 120, 32, 'attention', 'View Attention ↗', {
    fill: COLORS.attn.fill,
    stroke: COLORS.attn.stroke,
  });
  drawComponentLink(g, CX - 60, footerY, 120, 32, 'mlp', 'View MLP ↗', {
    fill: COLORS.mlp.fill,
    stroke: COLORS.mlp.stroke,
  });
  drawComponentLink(g, CX + 70, footerY, 120, 32, 'transformer-block', 'View Transformer Block ↗', {
    fill: COLORS.cross.fill,
    stroke: COLORS.cross.stroke,
  });
  footerY += 46;

  // Code annotation
  footerY = drawCodeAnnotation(
    g,
    80,
    footerY,
    W - 160,
    'Encoder-Decoder Block — PyTorch-style pseudocode',
    [`Params: ${fmtNum(metrics.totalParams)} · ~${fmtNum(metrics.flopsPerBlock)} FLOPs/block`],
    buildCodeLines(p)
  );

  return { width: W, height: footerY + 24, steps };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Step metadata builders
// ═══════════════════════════════════════════════════════════════════════════════

function makeInputStep(id: number, p: BlockParams, kind: 'encoder' | 'decoder'): BlockStep {
  const isEnc = kind === 'encoder';
  const seqLen = isEnc ? p.encLen : p.decLen;
  const name = isEnc ? 'Encoder input' : 'Decoder input';
  const varName = isEnc ? 'enc_in' : 'dec_in';
  return {
    id,
    label: name,
    shortLabel: isEnc ? 'Enc Input' : 'Dec Input',
    formula: `${varName} ∈ ℝ^(B×${seqLen}×${p.dModel})`,
    explanation: isEnc
      ? 'Source token hidden states enter the encoder. The encoder can attend bidirectionally to all source positions.'
      : 'Target token hidden states enter the decoder. The decoder self-attention is causal (masked) so each position only attends to earlier positions.',
    code: { title: name, lines: [`${varName} = ...  # [B, ${seqLen}, ${p.dModel}]`] },
    svgGroup: isEnc ? STEP_GROUPS.encInput : STEP_GROUPS.decInput,
    color: COLORS.input.stroke,
    fill: COLORS.input.fill,
  };
}

function makeNormStep(id: number, label: string, group: string, p: BlockParams): BlockStep {
  const params = p.normType === 'LayerNorm' ? p.dModel * 2 : p.dModel;
  return {
    id,
    label,
    shortLabel: label,
    formula: p.normType === 'LayerNorm' ? 'y = (x - μ) / (σ + ε) · γ + β' : 'y = x / RMS(x) · γ',
    explanation:
      p.normType === 'LayerNorm'
        ? 'LayerNorm normalizes across the hidden dimension and learns affine gain (γ) and bias (β) parameters.'
        : 'RMSNorm normalizes by the root-mean-square of the hidden dimension and learns only a gain parameter.',
    code: {
      title: p.normType,
      lines: [
        p.normType === 'LayerNorm'
          ? `self.norm = nn.LayerNorm(${p.dModel})  # ${fmtNum(params)} params`
          : `self.norm = RMSNorm(${p.dModel})       # ${fmtNum(params)} params`,
      ],
    },
    svgGroup: (STEP_GROUPS as Record<string, string>)[group],
    color: COLORS.norm.stroke,
    fill: COLORS.norm.fill,
  };
}

function makeAttnStep(id: number, title: string, group: string, p: BlockParams, seqLen: number): BlockStep {
  const isCross = group === 'crossAttn';
  const isCausal = group === 'decAttn';
  const kvDesc = isCross
    ? `K, V come from encoder output (length ${p.encLen})`
    : 'K, V come from the same input sequence';
  const maskDesc = isCausal
    ? 'A causal (lower-triangular) mask prevents attending to future decoder positions.'
    : 'No causal mask: every position attends to every position.';
  return {
    id,
    label: title,
    shortLabel: title,
    formula: isCross ? 'cross_out = softmax(Q_dec @ K_enc^T / √d_h) @ V_enc @ W_o' : 'attn_out = softmax(Q @ K^T / √d_h) @ V @ W_o',
    explanation: `${title} projects Q, K, V with ${p.nHeads} heads (d_head=${p.dHead}), computes scaled dot-product attention, applies ${isCausal ? 'causal masking and ' : ''}softmax, and projects back with W_o. ${kvDesc}. ${maskDesc}`,
    code: {
      title,
      lines: [
        `Q = x @ W_q  # [B, ${seqLen}, ${p.dModel}]`,
        isCross ? `K = enc_out @ W_k  # [B, ${p.encLen}, ${p.dModel}]` : `K = x @ W_k  # [B, ${seqLen}, ${p.dModel}]`,
        isCross ? `V = enc_out @ W_v  # [B, ${p.encLen}, ${p.dModel}]` : `V = x @ W_v  # [B, ${seqLen}, ${p.dModel}]`,
        `scores = Q @ K^T / sqrt(${p.dHead})`,
        isCausal ? 'scores = scores + causal_mask(-inf)' : '',
        `A = softmax(scores, dim=-1)`,
        `context = A @ V`,
        `${isCross ? 'cross_out' : 'attn_out'} = context @ W_o  # [B, ${seqLen}, ${p.dModel}]`,
      ].filter(Boolean),
    },
    svgGroup: (STEP_GROUPS as Record<string, string>)[group],
    color: isCross ? COLORS.cross.stroke : COLORS.attn.stroke,
    fill: isCross ? COLORS.cross.fill : COLORS.attn.fill,
  };
}

function makeFfnStep(id: number, title: string, group: string, p: BlockParams, seqLen: number): BlockStep {
  return {
    id,
    label: title,
    shortLabel: title,
    formula: 'ffn_out = GELU(x @ W_up) @ W_down',
    explanation: `The position-wise FFN expands the hidden dimension from ${p.dModel} to ${p.dFf}, applies GELU, then projects back to ${p.dModel}.`,
    code: {
      title,
      lines: [
        `up = x @ W_up          # [B, ${seqLen}, ${p.dFf}]`,
        `act = GELU(up)`,
        `ffn_out = act @ W_down # [B, ${seqLen}, ${p.dModel}]`,
      ],
    },
    svgGroup: (STEP_GROUPS as Record<string, string>)[group],
    color: COLORS.mlp.stroke,
    fill: COLORS.mlp.fill,
  };
}

function makeResStep(id: number, idx: number, prefix: string, formula: string, group: string): BlockStep {
  const shortPrefix = prefix === 'Encoder' ? 'Enc' : 'Dec';
  return {
    id,
    label: `${prefix} Residual Add ${idx}`,
    shortLabel: `${shortPrefix} Res ${idx}`,
    formula,
    explanation: 'Residual connections add the sub-layer input back to its output, preserving gradients through the deep encoder/decoder stacks.',
    code: { title: 'Residual Add', lines: [`x = x + sublayer_out  # shape unchanged`] },
    svgGroup: (STEP_GROUPS as Record<string, string>)[group],
    color: COLORS.residual.stroke,
    fill: COLORS.residual.fill,
  };
}

function makeOutputStep(id: number, p: BlockParams, kind: 'encoder' | 'decoder'): BlockStep {
  const isEnc = kind === 'encoder';
  const seqLen = isEnc ? p.encLen : p.decLen;
  const name = isEnc ? 'Encoder output' : 'Decoder output';
  return {
    id,
    label: name,
    shortLabel: isEnc ? 'Enc Out' : 'Dec Out',
    formula: `${isEnc ? 'enc_out' : 'dec_out'} ∈ ℝ^(B×${seqLen}×${p.dModel})`,
    explanation: isEnc
      ? 'The encoder output is a set of context vectors used as keys and values in decoder cross-attention.'
      : 'The decoder output is passed to the next decoder block or to the final language modeling head.',
    code: { title: name, lines: [`return ${isEnc ? 'enc_out' : 'dec_out'}  # [B, ${seqLen}, ${p.dModel}]`] },
    svgGroup: isEnc ? STEP_GROUPS.encOutput : STEP_GROUPS.decOutput,
    color: COLORS.output.stroke,
    fill: COLORS.output.fill,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Metrics
// ═══════════════════════════════════════════════════════════════════════════════

function computeMetrics(p: BlockParams) {
  // Encoder: self-attention (MHA) + FFN + 2 norms
  // Decoder: causal self-attention (MHA) + cross-attention (MHA) + FFN + 3 norms
  const attnParams = p.dModel * p.dModel * 4; // MHA: W_q, W_k, W_v, W_o
  const encAttnParams = attnParams;
  const decSelfAttnParams = attnParams;
  const decCrossAttnParams = attnParams;
  const ffnParams = p.dModel * p.dFf * 2;
  const normParamsPerNorm = p.normType === 'LayerNorm' ? p.dModel * 2 : p.dModel;
  const totalParams = encAttnParams + ffnParams + decSelfAttnParams + decCrossAttnParams + ffnParams + normParamsPerNorm * 5;

  const encAttnFlops = 6 * p.dModel * p.dModel * p.encLen + 2 * p.encLen * p.encLen * p.dModel;
  const encFfnFlops = 4 * p.dModel * p.dFf * p.encLen;
  const decSelfAttnFlops = 6 * p.dModel * p.dModel * p.decLen + 2 * p.decLen * p.decLen * p.dModel;
  const decCrossAttnFlops =
    2 * p.dModel * p.dModel * p.decLen +   // Q projection from decoder
    4 * p.dModel * p.dModel * p.encLen +   // K, V projections from encoder output
    2 * p.decLen * p.encLen * p.dModel;    // attention + context over enc_len × dec_len
  const decFfnFlops = 4 * p.dModel * p.dFf * p.decLen;
  const flopsPerBlock = encAttnFlops + encFfnFlops + decSelfAttnFlops + decCrossAttnFlops + decFfnFlops;

  return {
    attnParams: encAttnParams + decSelfAttnParams + decCrossAttnParams,
    ffnParams: ffnParams * 2,
    normParams: normParamsPerNorm * 5,
    totalParams,
    flopsPerBlock,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Text helpers
// ═══════════════════════════════════════════════════════════════════════════════

function insightText(p: BlockParams): string {
  return `Encoder-decoder blocks power seq2seq models such as T5 and BART. The encoder builds bidirectional source representations, while the decoder generates target tokens left-to-right with causal self-attention and cross-attention over encoder outputs. With ${p.normType}, each sub-layer is normalized before it runs (pre-norm), which stabilizes training for deep stacks.`;
}

function perfText(p: BlockParams, metrics: ReturnType<typeof computeMetrics>): string {
  return `This block contains three MHA sub-layers (encoder self, decoder causal, decoder cross) and two FFNs, totaling ${fmtNum(metrics.totalParams)} parameters. Attention cost scales quadratically with sequence length (${p.encLen} encoder, ${p.decLen} decoder tokens), while FFN cost is linear in length and dominates for long sequences. Overall ~${fmtNum(metrics.flopsPerBlock)} FLOPs per block.`;
}

function buildCodeLines(p: BlockParams): string[] {
  const normCtor = p.normType === 'LayerNorm' ? `nn.LayerNorm(${p.dModel})` : `RMSNorm(${p.dModel})`;
  return [
    `self.enc_norm1 = ${normCtor}`,
    `self.enc_attn = MHA(d_model=${p.dModel}, n_heads=${p.nHeads})`,
    `self.enc_norm2 = ${normCtor}`,
    `self.enc_ffn = FFN(d_model=${p.dModel}, d_ff=${p.dFf})`,
    `self.dec_norm1 = ${normCtor}`,
    `self.dec_attn = MHA(d_model=${p.dModel}, n_heads=${p.nHeads}, causal=True)`,
    `self.cross_norm = ${normCtor}`,
    `self.cross_attn = MHA(d_model=${p.dModel}, n_heads=${p.nHeads})`,
    `self.dec_norm3 = ${normCtor}`,
    `self.dec_ffn = FFN(d_model=${p.dModel}, d_ff=${p.dFf})`,
    '',
    'def forward(self, enc_in, dec_in):',
    '    # Encoder',
    '    enc_add1 = enc_in + self.enc_attn(self.enc_norm1(enc_in))',
    '    enc_out = enc_add1 + self.enc_ffn(self.enc_norm2(enc_add1))',
    '    # Decoder',
    '    dec_add1 = dec_in + self.dec_attn(self.dec_norm1(dec_in))',
    '    cross = self.cross_attn(self.cross_norm(dec_add1), kv=enc_out)',
    '    dec_add2 = dec_add1 + cross',
    '    dec_out = dec_add2 + self.dec_ffn(self.dec_norm3(dec_add2))',
    '    return enc_out, dec_out',
  ];
}
